// [데모 모드] '주문' 시트에서 읽어온 것과 같은 형식의 최근 35일 샘플 데이터
// (워크플로 ①이 기록하는 열 이름과 동일)
const products = [
  ['[1+1] 국산 무농약 현미 4kg', 32900, 9],
  ['제주 감귤 5kg 가정용', 20900, 7],
  ['유기농 귀리 1kg', 12900, 5],
  ['햇 찹쌀 2kg', 15900, 3],
  ['국산 서리태 1kg', 18900, 2],
  ['혼합 잡곡 선물세트', 45000, 1],
];
// 재현 가능한 의사난수 (매번 같은 데모 결과)
let seed = 20261104;
const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);

const rows = [];
const now = Date.now() + 9 * 3600e3; // KST 기준
for (let day = 35; day >= 1; day--) {
  const base = new Date(now - day * 86400e3);
  const weekend = [0, 6].includes(base.getUTCDay());
  const n = Math.round((weekend ? 14 : 22) + rnd() * 10 + (35 - day) * 0.3);
  for (let k = 0; k < n; k++) {
    const pick = rnd() * 27;
    let acc = 0;
    const p = products.find(([, , w]) => (acc += w) >= pick) || products[0];
    const qty = rnd() < 0.8 ? 1 : 2;
    const t = new Date(base);
    t.setUTCHours(Math.floor(rnd() * 24), Math.floor(rnd() * 60), 0);
    const iso = t.toISOString();
    rows.push({
      결제일시: `${iso.slice(0, 10)} ${iso.slice(11, 19)}`,
      상품주문번호: `D${iso.slice(0, 10).replace(/-/g, '')}${String(k).padStart(4, '0')}`,
      상품명: p[0],
      수량: qty,
      결제금액: p[1] * qty,
    });
  }
}
return rows.map((json) => ({ json }));

// 어제(KST) 매출 집계 + 지난주 같은 요일 / 최근 7일 평균 비교 + 상품 TOP5
const rows = $input.all().map((i) => i.json);

const kstNow = new Date(Date.now() + 9 * 3600e3);
const dayStr = (offset) => new Date(kstNow.getTime() - offset * 86400e3).toISOString().slice(0, 10);
const target = dayStr(1);
const lastWeek = dayStr(8);
const recent7 = Array.from({ length: 7 }, (_, i) => dayStr(i + 2)); // 어제 이전 7일

const byDay = {};
const seen = new Set();
for (const r of rows) {
  const date = String(r.결제일시 || '').slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) continue;
  const id = String(r.상품주문번호 || '');
  if (id) { if (seen.has(id)) continue; seen.add(id); }
  const amount = Number(String(r.결제금액).replace(/[^0-9.-]/g, '')) || 0;
  const qty = Number(r.수량) || 0;
  const d = (byDay[date] ||= { orders: 0, revenue: 0, items: 0, products: {} });
  d.orders += 1;
  d.revenue += amount;
  d.items += qty;
  const p = (d.products[r.상품명 || '(이름 없음)'] ||= { qty: 0, revenue: 0 });
  p.qty += qty;
  p.revenue += amount;
}

const empty = { orders: 0, revenue: 0, items: 0, products: {} };
const y = byDay[target] || empty;
const lw = byDay[lastWeek] || empty;
const avg7 = recent7.reduce((s, d) => s + (byDay[d]?.revenue || 0), 0) / 7;
const pct = (a, b) => (b ? Math.round(((a - b) / b) * 1000) / 10 : null);

const top = Object.entries(y.products)
  .map(([name, v]) => ({ name, ...v }))
  .sort((a, b) => b.revenue - a.revenue)
  .slice(0, 5);

const trend = [...recent7].reverse().concat(target).map((d) => ({ date: d, revenue: byDay[d]?.revenue || 0 }));

return [{
  json: {
    date: target,
    weekday: '일월화수목금토'[new Date(target + 'T00:00:00Z').getUTCDay()],
    orders: y.orders,
    revenue: y.revenue,
    items: y.items,
    avgOrderValue: y.orders ? Math.round(y.revenue / y.orders) : 0,
    lastWeekRevenue: lw.revenue,
    vsLastWeekPct: pct(y.revenue, lw.revenue),
    avg7Revenue: Math.round(avg7),
    vsAvg7Pct: pct(y.revenue, avg7),
    top,
    trend,
  },
}];

// 집계 결과 → Claude에게 한 줄 코멘트 요청
const cfg = $('설정').first().json;
const s = $input.first().json;

const request = {
  model: cfg.model,
  max_tokens: 4000,
  system: [
    `당신은 온라인 쇼핑몰 "${cfg.shopName}" 사장님의 매출 비서입니다.`,
    '주어진 숫자만 근거로, 사장님이 아침에 읽을 코멘트를 2~3문장으로 씁니다.',
    '- 첫 문장: 어제 실적을 지난주 같은 요일·최근 7일 평균과 비교해 한마디로 평가',
    '- 둘째 문장: 눈에 띄는 상품이나 변화 1가지',
    '- (선택) 셋째 문장: 오늘 해볼 만한 행동 1가지',
    '숫자를 지어내지 말고, 과장하지 말고, 이모지·마크다운 없이 평문으로 쓰세요.',
  ].join('\n'),
  messages: [{ role: 'user', content: `어제 매출 데이터(JSON):\n${JSON.stringify(s)}` }],
  output_config: { effort: 'low' },
  fallbacks: 'default',
};
return [{ json: { ...s, request } }];

// Claude 응답에서 코멘트 추출 (실패하면 빈 값 → 기본 코멘트 사용)
const res = $input.first().json;
const stats = $('AI 요청 구성').first().json;
const ok = res.stop_reason === 'end_turn';
const comment = ok
  ? (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('').trim()
  : '';
const { request, ...rest } = stats;
return [{ json: { ...rest, comment } }];

// 슬랙 메시지 + HTML 메일 본문 작성
const cfg = $('설정').first().json;
const s = $input.first().json;
const won = (n) => `${Math.round(Number(n)).toLocaleString('ko-KR')}원`;
const delta = (p) => (p === null || p === undefined ? '비교 데이터 없음' : `${p > 0 ? '▲' : p < 0 ? '▼' : ''}${Math.abs(p)}%`);

// AI 코멘트가 없으면 규칙 기반 기본 코멘트
const fallback = s.orders === 0
  ? '어제는 결제된 주문이 없었습니다. 판매처 연동 상태를 한번 확인해 보세요.'
  : `어제 매출은 지난주 같은 요일 대비 ${delta(s.vsLastWeekPct)}, 최근 7일 평균 대비 ${delta(s.vsAvg7Pct)}입니다.` +
    (s.top[0] ? ` 가장 많이 팔린 상품은 '${s.top[0].name}'입니다.` : '');
const comment = s.comment || fallback;

const max = Math.max(...s.trend.map((t) => t.revenue), 1);
const bars = s.trend.map((t) => {
  const n = Math.round((t.revenue / max) * 12);
  return `${t.date.slice(5)} ${'█'.repeat(n)}${'░'.repeat(12 - n)} ${won(t.revenue)}`;
});

const slackText = [
  `📊 *${cfg.shopName} 일일 매출 리포트* · ${s.date} (${s.weekday})`,
  `*매출 ${won(s.revenue)}* · 주문 ${s.orders}건 · 객단가 ${won(s.avgOrderValue)}`,
  `지난주 ${s.weekday}요일 대비 ${delta(s.vsLastWeekPct)} · 7일 평균 대비 ${delta(s.vsAvg7Pct)}`,
  '',
  `💡 ${comment}`,
  '',
  '*인기 상품 TOP5*',
  ...(s.top.length ? s.top.map((p, i) => `${i + 1}. ${p.name} — ${p.qty}개 / ${won(p.revenue)}`) : ['(없음)']),
  '',
  '*최근 8일 추이*',
  '```' + bars.join('\n') + '```',
].join('\n');

const esc = (t) => String(t).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const color = (p) => (p > 0 ? '#1a7f37' : p < 0 ? '#cf222e' : '#57606a');
const html = `
<div style="font-family:-apple-system,'Apple SD Gothic Neo','Malgun Gothic',sans-serif;max-width:560px;margin:0 auto;color:#1f2328">
  <p style="color:#57606a;margin:0">${esc(cfg.shopName)} · ${s.date} (${s.weekday})</p>
  <h1 style="font-size:28px;margin:4px 0 0">${won(s.revenue)}</h1>
  <p style="margin:4px 0 16px">주문 ${s.orders}건 · 객단가 ${won(s.avgOrderValue)}</p>
  <table style="width:100%;border-collapse:collapse;margin-bottom:16px">
    <tr><td style="padding:8px;background:#f6f8fa">지난주 ${s.weekday}요일 대비</td>
        <td style="padding:8px;background:#f6f8fa;text-align:right;color:${color(s.vsLastWeekPct)}"><b>${delta(s.vsLastWeekPct)}</b> (${won(s.lastWeekRevenue)})</td></tr>
    <tr><td style="padding:8px">최근 7일 평균 대비</td>
        <td style="padding:8px;text-align:right;color:${color(s.vsAvg7Pct)}"><b>${delta(s.vsAvg7Pct)}</b> (${won(s.avg7Revenue)})</td></tr>
  </table>
  <div style="padding:12px 16px;background:#ddf4ff;border-radius:8px;margin-bottom:16px">💡 ${esc(comment)}</div>
  <h3 style="margin:0 0 8px">인기 상품 TOP5</h3>
  <table style="width:100%;border-collapse:collapse">
    ${s.top.map((p, i) => `<tr><td style="padding:6px 0;border-bottom:1px solid #d0d7de">${i + 1}. ${esc(p.name)}</td><td style="padding:6px 0;border-bottom:1px solid #d0d7de;text-align:right">${p.qty}개 · ${won(p.revenue)}</td></tr>`).join('')}
  </table>
  <p style="color:#8c959f;font-size:12px;margin-top:24px">이 메일은 n8n 자동화로 매일 아침 발송됩니다.</p>
</div>`;

return [{
  json: {
    ...s,
    comment,
    slackText,
    emailSubject: `[${cfg.shopName}] ${s.date} 매출 ${won(s.revenue)} (${delta(s.vsLastWeekPct)})`,
    emailHtml: html,
  },
}];
